package net.mandomc.gameplay.dungeon;
import java.io.File;import java.util.*;
import org.bukkit.*;import org.bukkit.block.data.BlockData;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.entity.BlockDisplay;import org.bukkit.plugin.java.JavaPlugin;
/** Native animated panels. Door artwork is operator map data, not a plugin or paid dependency. */
public final class NativeGates implements AutoCloseable {
 private record Cell(JabbaSettings.Pos pos,BlockData data){}
 private record Motion(int id,List<BlockDisplay> displays,List<Location> origins,JabbaSettings.Pos delta,int start,Runnable done){}
 private final String ownerTag;private final Map<Integer,List<Cell>> destinations=new HashMap<>();private final Map<String,JabbaSettings.Pos> parkingAir=new LinkedHashMap<>();private final World world;private final int duration;private final Map<Integer,List<Cell>> panels=new LinkedHashMap<>();private final List<JabbaSettings.Pos> imported=new ArrayList<>();private final Map<Integer,Motion> moving=new LinkedHashMap<>();private final Set<Integer> open=new HashSet<>();private final org.bukkit.scheduler.BukkitTask task;
 public NativeGates(JavaPlugin plugin,World world,JabbaSettings settings,File file) throws Exception {
  this.world=world;ownerTag="mandomc_jabba_gate_"+settings.profile();duration=settings.animation();var c=new YamlConfiguration();c.load(file);if(c.getInt("schema-version")!=1||!settings.world().equals(c.getString("world")))throw new IllegalArgumentException("Invalid private gate blueprint world/schema");
  var used=new HashSet<String>();int total=0;
  for(var room:settings.rooms()){var p=c.getConfigurationSection("gates."+room.gate());if(p==null)throw new IllegalArgumentException("Missing gate panel "+room.gate());var cells=new ArrayList<Cell>();
   for(String s:p.getStringList("blocks")){var pair=s.split("\\|",2);if(pair.length!=2)throw new IllegalArgumentException("Invalid panel block");var pos=JabbaSettings.Pos.parse(pair[0]);if(!used.add(pos.key())||++total>4096)throw new IllegalArgumentException("Overlapping/oversized gate panels");var data=Bukkit.createBlockData(pair[1]);if(data.getMaterial().isInteractable()&&data.getMaterial()!=Material.IRON_TRAPDOOR&&data.getMaterial()!=Material.OAK_TRAPDOOR)throw new IllegalArgumentException("Gate panels cannot contain containers/devices");cells.add(new Cell(pos,data));}
   if(cells.isEmpty())throw new IllegalArgumentException("Empty panel");panels.put(room.gate(),List.copyOf(cells));for(String s:p.getStringList("clear-imported"))imported.add(JabbaSettings.Pos.parse(s));
  }
  var importedKeys=new HashSet<String>();imported.forEach(p->importedKeys.add(p.key()));
  for(var room:settings.rooms()){var own=new HashSet<String>();panels.get(room.gate()).forEach(cell->own.add(cell.pos.key()));var target=new ArrayList<Cell>();for(var cell:panels.get(room.gate())){var p=cell.pos;var move=room.movement();var dest=new JabbaSettings.Pos(p.x()+move.x(),p.y()+move.y(),p.z()+move.z());if(!settings.contains(p.location(world))||!settings.contains(dest.location(world)))throw new IllegalArgumentException("Gate outside operation bounds");if(cell.data.getMaterial().isAir())continue;if(own.contains(dest.key())||importedKeys.contains(dest.key())||dest.location(world).getBlock().getType().isAir()){target.add(new Cell(dest,cell.data));if(!own.contains(dest.key()))parkingAir.put(dest.key(),dest);}}destinations.put(room.gate(),List.copyOf(target));}
  task=Bukkit.getScheduler().runTaskTimer(plugin,this::tick,1,1);
 }
 public List<String> resetPlan(){var result=new ArrayList<String>();panels.values().forEach(cells->cells.forEach(c->result.add(c.pos.key()+"|"+c.data.getAsString())));imported.forEach(p->result.add(p.key()+"|minecraft:air"));parkingAir.values().forEach(p->result.add(p.key()+"|minecraft:air"));return result;}
 public boolean owns(Location loc){if(loc.getWorld()!=world)return false;var key=loc.getBlockX()+","+loc.getBlockY()+","+loc.getBlockZ();return panels.values().stream().flatMap(Collection::stream).anyMatch(c->c.pos.key().equals(key));}
 public void reset(){cancelMotions();parkingAir.values().forEach(p->p.location(world).getBlock().setType(Material.AIR,false));for(var pos:imported)pos.location(world).getBlock().setType(Material.AIR,false);panels.values().forEach(cells->cells.forEach(c->c.pos.location(world).getBlock().setBlockData(c.data,false)));open.clear();}
 public void open(int id,JabbaSettings.Pos delta,Runnable done){if(!panels.containsKey(id)||moving.containsKey(id)||open.contains(id))throw new IllegalStateException("Gate unavailable");var displays=new ArrayList<BlockDisplay>();var origins=new ArrayList<Location>();
  for(var cell:panels.get(id)){var location=cell.pos.location(world);if(!cell.data.getMaterial().isAir()){var display=world.spawn(location,BlockDisplay.class,e->{e.setBlock(cell.data);e.setPersistent(false);e.setGravity(false);e.setTeleportDuration(2);e.addScoreboardTag("mandomc_jabba_gate");e.addScoreboardTag(ownerTag);});displays.add(display);origins.add(location);location.getBlock().setType(Material.BARRIER,false);}else location.getBlock().setType(Material.AIR,false);}
  moving.put(id,new Motion(id,displays,origins,delta,Bukkit.getCurrentTick(),done));world.playSound(origins.isEmpty()?world.getSpawnLocation():origins.getFirst(),Sound.BLOCK_PISTON_EXTEND,1,0.55f);
 }
 private void tick(){var completed=new ArrayList<Runnable>();for(var it=moving.values().iterator();it.hasNext();){var m=it.next();double t=Math.min(1,(Bukkit.getCurrentTick()-m.start)/(double)duration),p=t*t*(3-2*t);for(int i=0;i<m.displays.size();i++)m.displays.get(i).teleport(m.origins.get(i).clone().add(m.delta.x()*p,m.delta.y()*p,m.delta.z()*p));if(t>=1){m.displays.forEach(BlockDisplay::remove);panels.get(m.id).forEach(c->c.pos.location(world).getBlock().setType(Material.AIR,false));destinations.get(m.id).forEach(c->{var b=c.pos.location(world).getBlock();if(b.getType().isAir())b.setBlockData(c.data,false);});open.add(m.id);completed.add(m.done);it.remove();}}completed.forEach(Runnable::run);}
 private void cancelMotions(){moving.values().forEach(m->m.displays.forEach(BlockDisplay::remove));moving.clear();}
 public void close(){task.cancel();cancelMotions();}
}
